def apply_normalization(norm_name, value, min_val, max_val):
    norms = {'min_max': lambda v, lo, hi: (v - lo) / (hi - lo) if hi != lo else 0, 'clamp': lambda v, lo, hi: max(lo, min(hi, v)), 'z_score': lambda v, lo, hi: (v - lo) / hi if hi != 0 else 0}
    fn = norms.get(norm_name)
    if not fn:
        raise ValueError('Unknown normalization')
    return fn(value, min_val, max_val)

